+func connectSSHAgent(ctx context.Context) sshagent.Agent {
+	sock := os.Getenv("SSH_AUTH_SOCK")
+	if sock == "" {
+		return nil
+	}
+
+	var d net.Dialer
+	conn, err := d.DialContext(ctx, "unix", sock)
+	if err != nil {
+		return nil
+	}
+
+	return sshagent.NewClient(conn)
+}
